import React, { useState } from 'react';
import { gql, useQuery, useMutation } from '@apollo/client';

// ============================================================
// HELPER
// ============================================================
function formatDuration(seconds) {
  if (!seconds && seconds !== 0) return '—';
  const m = Math.floor(seconds / 60);
  const s = String(seconds % 60).padStart(2, '0');
  return `${m}:${s}`;
}

// ============================================================
// QUERIES & MUTATIONS
// ============================================================
const PLAYLISTS_QUERY = gql`
  query Playlists {
    playlists {
      id
      title
      description
      public
      nb_tracks
    }
  }
`;

const PLAYLIST_DETAIL_QUERY = gql`
  query Playlist($id: ID!) {
    playlist(id: $id) {
      id
      title
      description
      public
      nb_tracks
      tracks {
        id
        title
        duration
        explicit_lyrics
        artist {
          name
        }
      }
    }
  }
`;

const CREATE_PLAYLIST_MUTATION = gql`
  mutation CreatePlaylist($input: CreatePlaylistInput!) {
    createPlaylist(input: $input) {
      id
      title
    }
  }
`;

const DELETE_PLAYLIST_MUTATION = gql`
  mutation DeletePlaylist($id: ID!) {
    deletePlaylist(id: $id) {
      success
    }
  }
`;

const ADD_TRACK_TO_PLAYLIST_MUTATION = gql`
  mutation AddTrackToPlaylist($playlistId: ID!, $trackId: ID!) {
    addTrackToPlaylist(playlistId: $playlistId, trackId: $trackId) {
      id
      nb_tracks
    }
  }
`;

const REMOVE_TRACK_FROM_PLAYLIST_MUTATION = gql`
  mutation RemoveTrackFromPlaylist($playlistId: ID!, $trackId: ID!) {
    removeTrackFromPlaylist(playlistId: $playlistId, trackId: $trackId) {
      id
      nb_tracks
    }
  }
`;

const TRACKS_QUERY = gql`
  query Tracks {
    tracks(limit: 100) {
      nodes {
        id
        title
        artist {
          name
        }
      }
    }
  }
`;

// ============================================================
// COMPOSANT
// ============================================================
export default function Playlists({ token }) {
  const [selectedPlaylist, setSelectedPlaylist] = useState(null);
  const [showForm, setShowForm]                 = useState(false);
  const [formData, setFormData]                 = useState({
    title:       '',
    description: '',
    public:      true,
  });
  const [error, setError]     = useState('');
  const [success, setSuccess] = useState('');

  const authHeaders = { context: { headers: { authorization: `Bearer ${token}` } } };

  const { data, loading, error: queryError, refetch } = useQuery(PLAYLISTS_QUERY, authHeaders);

  const { data: playlistDetail, loading: detailLoading } = useQuery(PLAYLIST_DETAIL_QUERY, {
    variables: { id: selectedPlaylist },
    skip: !selectedPlaylist,
    ...authHeaders,
  });

  const { data: tracksData } = useQuery(TRACKS_QUERY, authHeaders);

  const [createPlaylist, { loading: createLoading }] = useMutation(CREATE_PLAYLIST_MUTATION, {
    ...authHeaders,
    onCompleted: () => {
      setSuccess('Playlist créée !');
      setFormData({ title: '', description: '', public: true });
      setShowForm(false);
      refetch();
    },
    onError: (err) => setError(err.message),
  });

  const [deletePlaylist] = useMutation(DELETE_PLAYLIST_MUTATION, {
    ...authHeaders,
    onCompleted: () => {
      setSuccess('Playlist supprimée !');
      setSelectedPlaylist(null);
      refetch();
    },
    onError: (err) => setError(err.message),
  });

  const [addTrack] = useMutation(ADD_TRACK_TO_PLAYLIST_MUTATION, {
    ...authHeaders,
    onCompleted: () => { setSuccess('Piste ajoutée !'); refetch(); },
    onError: (err) => setError(err.message),
  });

  const [removeTrack] = useMutation(REMOVE_TRACK_FROM_PLAYLIST_MUTATION, {
    ...authHeaders,
    onCompleted: () => { setSuccess('Piste retirée !'); refetch(); },
    onError: (err) => setError(err.message),
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    createPlaylist({
      variables: {
        input: {
          title:       formData.title,
          description: formData.description || undefined,
          public:      formData.public,
        },
      },
    });
  };

  if (loading)    return <div className="loading">⏳ Chargement des playlists...</div>;
  if (queryError) return <div className="error">❌ Erreur : {queryError.message}</div>;

  const playlists = data?.playlists || [];

  // ---- Vue détail ----
  if (selectedPlaylist) {
    const pl = playlistDetail?.playlist;
    return (
      <div>
        <button onClick={() => setSelectedPlaylist(null)} className="btn-secondary">
          ← Retour
        </button>

        {error   && <div className="error">{error}</div>}
        {success && <div className="success">{success}</div>}

        {detailLoading && <div className="loading">⏳ Chargement...</div>}

        {pl && (
          <div className="card" style={{ maxWidth: '100%', marginTop: '1rem' }}>
            <h3>{pl.title}</h3>
            {pl.description && <p>{pl.description}</p>}

            <div className="card-meta">
              <span>🎵 {pl.nb_tracks ?? pl.tracks?.length ?? 0} piste{(pl.nb_tracks ?? pl.tracks?.length) > 1 ? 's' : ''}</span>
              <span>{pl.public ? '🌐 Publique' : '🔒 Privée'}</span>
            </div>

            <div className="card-actions" style={{ marginTop: '1rem' }}>
              <button
                onClick={() => {
                  if (window.confirm(`Supprimer "${pl.title}" ?`)) {
                    deletePlaylist({ variables: { id: selectedPlaylist } });
                  }
                }}
                className="btn-danger"
              >
                🗑️ Supprimer la playlist
              </button>
            </div>

            <h4 style={{ marginTop: '2rem', marginBottom: '1rem' }}>Ajouter une piste</h4>
            <select
              defaultValue=""
              onChange={(e) => {
                if (e.target.value) {
                  addTrack({ variables: { playlistId: selectedPlaylist, trackId: e.target.value } });
                  e.target.value = '';
                }
              }}
              style={{ width: '100%', padding: '0.75rem', marginBottom: '1rem' }}
            >
              <option value="">Sélectionner une piste…</option>
              {tracksData?.tracks?.nodes?.map((track) => (
                <option key={track.id} value={track.id}>
                  {track.title} — {track.artist?.name}
                </option>
              ))}
            </select>

            <h4 style={{ marginTop: '2rem', marginBottom: '1rem' }}>Pistes</h4>
            {pl.tracks?.length === 0 && (
              <div className="empty">📭 Aucune piste dans cette playlist</div>
            )}
            {pl.tracks?.map((track, idx) => (
              <div
                key={track.id}
                style={{
                  display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                  padding: '0.75rem',
                  background: '#f5f5f5',
                  marginBottom: '0.5rem',
                  borderRadius: '4px',
                }}
              >
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', flex: 1, minWidth: 0 }}>
                  <span style={{ color: '#999', minWidth: 20, textAlign: 'right', fontSize: 13 }}>{idx + 1}</span>
                  <div style={{ minWidth: 0 }}>
                    <strong style={{ display: 'block', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                      {track.explicit_lyrics && (
                        <span style={{
                          background: '#FCEBEB', color: '#A32D2D',
                          fontSize: 10, fontWeight: 600, padding: '1px 5px',
                          borderRadius: 3, marginRight: 6,
                        }}>E</span>
                      )}
                      {track.title}
                    </strong>
                    <span style={{ color: '#999', fontSize: 13 }}>{track.artist?.name}</span>
                  </div>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', flexShrink: 0 }}>
                  <span style={{ color: '#999', fontSize: 13 }}>{formatDuration(track.duration)}</span>
                  <button
                    onClick={() => removeTrack({ variables: { playlistId: selectedPlaylist, trackId: track.id } })}
                    className="btn-danger"
                    style={{ padding: '0.25rem 0.5rem', fontSize: '0.8rem' }}
                  >
                    ✕
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  }

  // ---- Vue liste ----
  return (
    <div>
      <h2>📋 Mes Playlists</h2>

      {error   && <div className="error">{error}</div>}
      {success && <div className="success">{success}</div>}

      <div className="filter-section">
        <button onClick={() => setShowForm(!showForm)} className="btn-primary">
          {showForm ? '❌ Annuler' : '➕ Créer une playlist'}
        </button>

        {showForm && (
          <form onSubmit={handleSubmit} style={{ marginTop: '1rem' }}>
            <div className="form-group">
              <label>Titre *</label>
              <input
                type="text"
                value={formData.title}
                onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                required
              />
            </div>

            <div className="form-group">
              <label>Description</label>
              <textarea
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                style={{ width: '100%', minHeight: '80px', padding: '0.75rem' }}
              />
            </div>

            <div className="form-group" style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
              <input
                type="checkbox"
                id="public"
                checked={formData.public}
                onChange={(e) => setFormData({ ...formData, public: e.target.checked })}
              />
              <label htmlFor="public" style={{ margin: 0 }}>Playlist publique</label>
            </div>

            <button type="submit" className="btn-success" disabled={createLoading}>
              {createLoading ? '⏳ Création...' : '✅ Créer'}
            </button>
          </form>
        )}
      </div>

      <div className="items-grid">
        {playlists.map((playlist) => (
          <div
            key={playlist.id}
            className="card"
            onClick={() => setSelectedPlaylist(playlist.id)}
            style={{ cursor: 'pointer' }}
          >
            <h3>{playlist.title}</h3>
            {playlist.description && <p>{playlist.description}</p>}
            <div className="card-meta">
              <span>🎵 {playlist.nb_tracks ?? 0} piste{playlist.nb_tracks > 1 ? 's' : ''}</span>
              <span>{playlist.public ? '🌐 Publique' : '🔒 Privée'}</span>
            </div>
          </div>
        ))}
      </div>

      {playlists.length === 0 && <div className="empty">📭 Aucune playlist</div>}
    </div>
  );
}
